    const paid=this.core.spendClubChips(MAFIA_GAME.entryCost);if(!paid.ok)return this.result(false,`A round costs ${MAFIA_GAME.entryCost} fictional Club Chips. ${paid.message}`);
    const opponents=MAFIA_OPPONENTS.slice(0,opponentCount),participants=[{id:"player",name:"You",avatar:"🧑‍💼",human:true,personality:"Fruitopia Tycoon",risk:.5,bluff:.5,preferred:[],targeting:"leader"},...opponents].map((item,seat)=>({...copy(item),seat,alive:true,spectator:false,hand:[],protectedBy:null,bodyguardId:null,magnetic:false,partnerId:null,chainedTo:null,secondServingUsed:false,memory:{attackedBy:{},savedBy:{}},stats:{survived:0,rebounds:0,eliminations:0,saves:0,directAttacks:0}}));
