    this.state.event={id:event.id,name:event.name,icon:event.icon,status:"active",history:[]};this.log(`The Mystery Crate produced ${event.name}.`,"event");this.resolveEvent(event);this.armPending(event.id==="choose-a-card"?18:12);return this.result(true,event.name,{event:this.state.event,pending:this.state.pending});
