  beginCardChoice(){const choices=this.cardOptions(3);this.state.event={id:"choose-a-card",name:"Choose a Card",icon:"🃏",status:"active",history:[]};for(const npc of alive(this.state).filter(item=>!item.human)){const preferred=choices.find(option=>npc.preferred.includes(option.id));this.drawCard(npc,(preferred||choices[Math.floor(this.random()*choices.length)]).id);}this.state.pending={type:"card-choice",prompt:"Don Durian presents three cards. Inspect all three and keep one.",choices:choices.map(item=>item.id)};this.armPending(18);return this.result(true,"Choose one card.",{pending:this.state.pending});}
