    if(event.id==="target-card"){const actor=target,victim=other();if(actor.human){this.state.pending={type:"target-card",prompt:`Target card: ${victim.name}. Choose correctly before time runs out.`,actorId:actor.id,correctTarget:victim.id,targets:living.filter(item=>item.id!==actor.id).map(item=>item.id)};return;}const correct=this.random()<.7+actor.risk*.15;return this.launchAttack(correct?victim:actor,{source:event.name,type:"blaster",attackerId:actor.id,allowRebound:true});}
