    if(event.id==="sewer-rat"){const roll=this.random();if(roll<.25){this.core.addClubChips(3);this.log("The mechanical sewer rat dropped 3 Club Chips.","reward");}else if(roll<.5){this.drawCard(target);this.log(`The rat delivered a card to ${target.name}.`,"reward");}else if(roll<.75&&target.hand.length){const stolen=target.hand.splice(Math.floor(this.random()*target.hand.length),1)[0];const receiver=other();receiver.hand.push(stolen);this.log(`The rat moved one card from ${target.name} to ${receiver.name}.`,"card");}else{const receiver=other(),hand=target.hand;target.hand=receiver.hand;receiver.hand=hand;this.log(`The rat switched ${target.name} and ${receiver.name}'s hands.`,"card");}return this.finishEvent();}
