    if(event.id==="lights-out"){const sees=this.hasCard(human,"night-vision-lime");this.log(sees?`Night-Vision Lime reveals that ${target.name} was selected.`:"The green lights snapped off. A chair scraped in the dark.","event");return this.launchAttack(target,{source:event.name,type:"blaster",attackerId:"unknown",allowRebound:true});}
