    if(event.id==="mafia-duel"){const rival=other();if(target.human||rival.human){this.state.pending={type:"duel",prompt:`${target.name} faces ${rival.name}. Choose your timing. Either launcher may jam.`,targetId:target.id,partnerId:rival.id,options:["steady","quick","dodge"]};return;}return this.resolveDuel(target,rival,"steady");}
