  weapon(type){if(!this.state.familyFriendly)return({blaster:"Cartoon Blaster",knife:"Spring Knife",saw:"Buzz Saw",bomb:"Rotten Fruit Bomb"})[type]||"crate danger";return MAFIA_FAMILY_LABELS[type]||"cartoon crate surprise";}
  launchAttack(target,attack){if(!target?.alive)return this.finishEvent();const bodyguard=target.bodyguardId?this.player(target.bodyguardId):null;if(bodyguard?.alive&&bodyguard.id!==target.id){this.log(`${bodyguard.name} intercepted the event for ${target.name}.`,"card");target=bodyguard;}const sticky=this.hasCard(target,"sticky-banana"),knifeReactions=attack.type==="knife"&&(this.hasCard(target,"rebound-blade")||this.hasCard(target,"side-step"));const manual=!sticky&&(this.hasCard(target,"rebound")&&attack.allowRebound||this.hasCard(target,"banana-dodge")||knifeReactions);if(target.human&&manual){this.state.pending={type:"reaction",prompt:`${this.weapon(attack.type)} targets you. React now or take the hit.`,targetId:target.id,attack:{...attack,chain:attack.chain||[]},options:[...(attack.allowRebound&&this.hasCard(target,"rebound")?["rebound-left","rebound-right"]:[]),...(attack.type==="knife"&&this.hasCard(target,"rebound-blade")?["blade-back"]:[]),...(attack.type==="knife"&&this.hasCard(target,"side-step")?["side-step"]:[]),...(this.hasCard(target,"banana-dodge")?["dodge"]:[]),"take-hit"]};this.armPending(8);return;}return this.resolveAttack(target,attack);}
