    this.state.pending=null;const human=this.player(),target=this.player(pending.targetId),actor=this.player(pending.actorId);
    if(pending.type==="card-choice"){if(!pending.choices.includes(option))return this.restorePending(pending,"Choose one of the three offered cards.");const card=this.drawCard(human,option);this.log(`You chose ${MAFIA_CARD_BY_ID[card.cardId].name}.`,"card");this.finishEvent();return this.result(true,"Card added to your hand.");}
    if(pending.type==="knife-target"){if(option==="spare"){const card=this.hasCard(actor,"spare-them");if(!card)return this.restorePending(pending,"Spare Them is not available.");this.removeCard(actor,card.instanceId);this.core.state.sewer.mafia.reputation+=2;this.log("You used Spare Them, cancelled the Spring Knife, and gained 2 Mafia reputation.","safe");this.finishEvent();return this.result(true,"Attack cancelled for reputation.");}let victim=option==="left"?this.player(pending.leftId):option==="right"?this.player(pending.rightId):pending.anyTarget&&pending.targets.includes(option)?this.player(option):null;if(!victim||!pending.targets.includes(victim.id))return this.restorePending(pending,"The Spring Knife can only target the immediate living player on the left or right unless Choose Anyone is active.");if(![pending.leftId,pending.rightId].includes(victim.id)){const choose=this.hasCard(actor,"choose-anyone");if(!choose)return this.restorePending(pending,"Choose Anyone is no longer active.");this.removeCard(actor,choose.instanceId);}if(this.random()<.16){this.log(`Your ${this.weapon("knife")} jammed harmlessly.`,"safe");this.finishEvent();}else this.launchAttack(victim,{source:"Spring Knife",type:"knife",attackerId:actor.id,allowRebound:false});return this.result(true,"Knife choice locked.");}
