  resolvePile(target,index){if(!Number.isInteger(index)||index<0||index>4)return this.result(false,"Choose one of the five facedown cards.");const outcome=["positive","neutral","negative","jam","fire"][Math.floor(this.random()*5)];if(outcome==="jam"){this.log("The chosen card made the launcher jam.","safe");this.finishEvent();return this.result(true,"A safe jam.");}if(outcome==="fire"){this.launchAttack(target,{source:"Dangerous Card Pile",type:"blaster",attackerId:"crate",allowRebound:true});return this.result(true,"The pile fired!");}const cards=MAFIA_CARDS.filter(item=>item.alignment.toLowerCase()===outcome),drawn=this.drawCard(target,this.pick(cards).id);this.log(`${target.name} found ${MAFIA_CARD_BY_ID[drawn.cardId].name}.`,"card");this.finishEvent();return this.result(true,"Card pile resolved.");}
