  resolveSplit(first,second,a,b){if(a==="share"&&b==="share"){this.drawCard(first);this.drawCard(second);this.log(`${first.name} and ${second.name} shared; both received a card.`,"reward");}else if(a!==b){const winner=a==="snatch"?first:second;this.drawCard(winner);this.log(`${winner.name} snatched the only card.`,"card");}else this.log("Both players chose Snatch. The dispenser kept the reward.","safe");this.finishEvent();return this.result(true,"Split or Snatch resolved.");}
  resolveVote(humanVote){const voters=alive(this.state),votes={};for(const voter of voters){const target=voter.human?this.player(humanVote):this.chooseTarget(voter,voters.filter(item=>item.id!==voter.id));if(target)votes[target.id]=(votes[target.id]||0)+1;}const max=Math.max(...Object.values(votes)),candidates=Object.keys(votes).filter(id=>votes[id]===max),selected=this.player(this.pick(candidates));this.log(`${selected.name} received the most votes and faces the crate test.`,"event");if(this.random()<.3){this.log("The vote test released a shower of harmless grapes.","safe");this.finishEvent();}else this.launchAttack(selected,{source:"Mafia Vote",type:"blaster",attackerId:"table",allowRebound:true});return this.result(true,"Votes counted.");}
  resolveDuel(first,second,choice){const jamChance=choice==="steady"?.28:choice==="dodge"?.42:.16;if(this.random()<jamChance){this.log("Both duel launchers jammed at once.","safe");this.finishEvent();return this.result(true,"Double jam!");}const loser=choice==="dodge"?second:(this.random()<.5?first:second),attacker=loser.id===first.id?second:first;this.launchAttack(loser,{source:"Mafia Duel",type:"blaster",attackerId:attacker.id,allowRebound:false});return this.result(true,"The duel fired.");}
