  finishEvent(){if(this.state.event)this.state.event.status="resolved";this.state.pending=null;this.finishIfNeeded();return true;}
  finishIfNeeded(){const survivors=alive(this.state);if(this.state.status!=="active"||survivors.length>1)return false;const winner=survivors[0]||null;this.state.status="finished";this.state.winnerId=winner?.id||null;this.state.totalRounds=(this.state.totalRounds||0)+1;this.core.state.sewer.stats.mafiaRounds=(this.core.state.sewer.stats.mafiaRounds||0)+1;if(winner?.human)this.state.wins=(this.state.wins||0)+1;const human=this.player(),won=winner?.human,reward=won?{chips:30,cash:200,coins:3,xp:180,reputation:12}:{chips:6,cash:30,coins:0,xp:50,reputation:3};if(human?.partnerId===winner?.id){reward.chips+=5;reward.xp+=25;}if(human&&!human.stats.directAttacks&&won)reward.chips+=5;this.state.reward={...reward,roundId:this.state.roundId,winner:winner?.name||"The crate",won:Boolean(won)};this.state.rewardCollected=false;this.state.lastResult={roundId:this.state.roundId,winnerId:winner?.id||null,turns:this.state.turn};this.state.roundHistory.push(this.state.lastResult);this.state.roundHistory=this.state.roundHistory.slice(-20);this.log(`${winner?.name||"Nobody"} is the last fruit sitting!`,"winner");return true;}
